Think: Remove duplicates and exclude entries that are symlinks or are not actual directories from temp_workspace/verify_dirs.txt, producing temp_workspace/root_dirs_final.txt.

Act: bash

```bash
awk -F '\t' '{
 name=$1;
 if($2!~/PASS/) next;
 if(seen[name]++) next;
 cmd="/bin/test -L \"/" name "\"";
 if(system(cmd)==0) next;
 cmd="/bin/test -L \"" name "\"";
 if(system(cmd)==0) next;
 cmd="/bin/test -d \"/" name "\"";
 if(system(cmd)!=0){
   cmd2="/bin/test -d \"" name "\"";
   if(system(cmd2)!=0) next;
 }
 print name
}' temp_workspace/verify_dirs.txt > temp_workspace/root_dirs_final.txt
