Think: Normalize epoch timestamps in raw_timestamps.csv to ISO 8601 UTC, being careful with commas in file paths, and write results to normalized_timestamps.csv.

Act: bash

```bash
awk '{
 n = split($0, a, ",");
 ts = a[n];
 path = a[1];
 for(i=2;i<n;i++) path = path "," a[i];
 cmd = "date -u -d @"ts" +\"%Y-%m-%dT%H:%M:%SZ\"";
 cmd | getline t;
 close(cmd);
 print path "," t;
}' usr_scan_workspace/raw_timestamps.csv > usr_scan_workspace/normalized_timestamps.csv
